-- Generated by `chainindex dbt` from chains/ethereum.yaml and abis/UniswapV3Pool.json. Do not edit: change the chain file or ABI and regenerate.
-- CollectProtocol(address,address,uint128,uint128)
{{ config(
    materialized='view',
    schema='events_ethereum',
    alias='uniswap_v3_pool__collect_protocol',
    tags=['chains', 'chain_ethereum'],
) }}

select
    toUInt64(1) as chain_id,
    address,
    block_number,
    block_time,
    block_hash,
    transaction_hash,
    transaction_index,
    log_index,
    inserted_at,
    concat('0x', substring(substring(topic1, 3, 64), 25, 40)) as sender,
    concat('0x', substring(substring(topic2, 3, 64), 25, 40)) as recipient,
    toUInt128(reinterpretAsUInt256(reverse(unhex(substring(data, 3, 64))))) as amount0,
    toUInt128(reinterpretAsUInt256(reverse(unhex(substring(data, 67, 64))))) as amount1
from {{ source('chain_ethereum', 'logs') }}
where topic0 = '0x596b573906218d3411850b26a6b437d6c4522fdb43d2d2386263f86d50b8b151'
  and address in (select address from {{ ref('ethereum__contracts') }} where contract = 'uniswap_v3_pool')
  and (block_number, block_hash) not in (
    select block_number, block_hash from {{ source('chain_ethereum', 'orphaned_blocks') }}
  )
